css:
/* ---- Elegant Salary Slip · solid colours, no gradients ---- */
.print-format { padding: 0; color: #1f2937; font-family: "Helvetica Neue", Helvetica, Arial, sans-serif; }
.ps-wrap { padding: 6mm 7mm; }
* { -webkit-print-color-adjust: exact !important; print-color-adjust: exact !important; }

.ps-head { width: 100%; border-collapse: collapse; }
.ps-head td { vertical-align: middle; padding: 0; }
.ps-logo { width: 64px; height: 64px; object-fit: contain; }
.ps-co-name { font-size: 19px; font-weight: 700; color: #111827; margin: 0; line-height: 1.15; }
.ps-co-meta { font-size: 10.5px; color: #6b7280; line-height: 1.45; margin-top: 2px; }
.ps-title { font-size: 13px; font-weight: 700; letter-spacing: 0.14em; color: #4338ca; text-transform: uppercase; margin: 0; }
.ps-period { font-size: 11px; color: #374151; margin-top: 2px; }
.ps-slipno { font-size: 10px; color: #9ca3af; margin-top: 1px; }

.ps-rule { height: 3px; background: #4338ca; border: 0; margin: 8px 0 0 0; }

.ps-section-label { font-size: 10px; font-weight: 700; letter-spacing: 0.12em; text-transform: uppercase;
    color: #4338ca; margin: 14px 0 6px 0; }

.ps-emp { width: 100%; border-collapse: collapse; font-size: 11px; }
.ps-emp td { padding: 4px 8px; border: 1px solid #e5e7eb; vertical-align: top; }
.ps-emp .k { color: #6b7280; width: 18%; background: #f9fafb; font-weight: 600; }
.ps-emp .v { color: #111827; width: 32%; font-weight: 600; }

.ps-att { width: 100%; border-collapse: separate; border-spacing: 6px 0; margin-top: 2px; table-layout: fixed; }
.ps-att td { background: #f3f4f6; border: 1px solid #e5e7eb; border-radius: 6px; text-align: center; padding: 7px 4px; }
.ps-att .num { font-size: 16px; font-weight: 700; color: #111827; line-height: 1; }
.ps-att .lbl { font-size: 9px; color: #6b7280; text-transform: uppercase; letter-spacing: 0.06em; margin-top: 3px; }

.ps-comp { width: 100%; border-collapse: collapse; font-size: 11px; }
.ps-comp th { background: #1f2937; color: #fff; text-align: left; padding: 6px 10px; font-size: 10px;
    text-transform: uppercase; letter-spacing: 0.06em; font-weight: 600; }
.ps-comp th.amt, .ps-comp td.amt { text-align: right; }
.ps-comp td { padding: 5px 10px; border-bottom: 1px solid #eceef1; color: #374151; }
.ps-comp tr:nth-child(even) td { background: #fafafb; }
.ps-comp .ytd { color: #9ca3af; font-size: 9.5px; }
.ps-comp tfoot td { font-weight: 700; color: #111827; border-top: 2px solid #1f2937;
    background: #f3f4f6; padding: 7px 10px; }
.ps-earn th { background: #065f46; }
.ps-earn tfoot td { border-top-color: #065f46; }
.ps-ded th { background: #991b1b; }
.ps-ded tfoot td { border-top-color: #991b1b; }

.ps-cols { width: 100%; border-collapse: collapse; }
.ps-cols > tbody > tr > td { vertical-align: top; width: 50%; padding: 0; }
.ps-cols .gap { width: 12px; padding: 0; }

.ps-net { width: 100%; border-collapse: collapse; margin-top: 14px; background: #4338ca; border-radius: 8px; }
.ps-net td { padding: 12px 16px; color: #fff; vertical-align: middle; }
.ps-net .np-lbl { font-size: 10px; letter-spacing: 0.12em; text-transform: uppercase; opacity: 0.85; }
.ps-net .np-amt { font-size: 26px; font-weight: 700; line-height: 1.1; }
.ps-net .np-words { font-size: 10.5px; opacity: 0.9; font-style: italic; text-align: right; }

.ps-tax { width: 100%; border-collapse: collapse; font-size: 10.5px; margin-top: 12px; }
.ps-tax td { border: 1px solid #e5e7eb; padding: 5px 10px; }
.ps-tax .k { background: #f9fafb; color: #6b7280; font-weight: 600; }
.ps-tax .v { text-align: right; font-weight: 600; color: #111827; }

.ps-foot { margin-top: 16px; padding-top: 8px; border-top: 1px solid #e5e7eb;
    text-align: center; font-size: 9.5px; color: #9ca3af; }

.ps-watermark { position: fixed; top: 120mm; left: 0; width: 100%; text-align: center;
    font-size: 80px; font-weight: 700; color: #000; opacity: 0.05;
    -webkit-transform: rotate(-30deg); transform: rotate(-30deg); z-index: 0; }

/* ---- bilingual (Hindi) sub-labels ---- */
.hi { display: block; font-size: 0.82em; font-weight: 500; line-height: 1.35;
    opacity: 0.78; text-transform: none; letter-spacing: 0; margin-top: 1px;
    font-family: "Noto Sans Devanagari", "Nirmala UI", "Mangal", "Lohit Devanagari", "Kohinoor Devanagari", sans-serif; }
.ps-comp .hi, .ps-emp .k .hi { opacity: 0.7; }
